package com.app.eventmanagmentsystem.model.audit;

import jakarta.persistence.*;
import lombok.Getter;
import lombok.Setter;
import org.hibernate.annotations.UuidGenerator;
import org.springframework.data.annotation.CreatedDate;
import org.springframework.data.annotation.LastModifiedDate;
import org.springframework.data.jpa.domain.support.AuditingEntityListener;

import java.time.Instant;
import java.util.UUID;

/**
 * Common audit fields inherited by every business entity.
 *
 * UUID is auto-generated by Hibernate (random strategy). Timestamps are managed
 * by Spring Data JPA auditing. Actor fields are populated via
 * {@link AuditingEntityListener} + {@link SecurityAuditorAware}.
 */
@Getter
@Setter
@MappedSuperclass
@EntityListeners(AuditingEntityListener.class)
public abstract class BaseEntity {

    @Id
    @UuidGenerator(style = UuidGenerator.Style.RANDOM)
    @Column(name = "id", updatable = false, nullable = false, columnDefinition = "BINARY(16)")
    private UUID id;

    @CreatedDate
    @Column(name = "created_at", updatable = false, nullable = false)
    private Instant createdAt;

    @LastModifiedDate
    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    /**
     * UUID of the user who created this record, as a string to allow null
     * (anonymous registration, system bootstrap).
     */
    @Column(name = "created_by_id", updatable = false, length = 36)
    private String createdById;

    @Column(name = "created_by_name", updatable = false, length = 150)
    private String createdByName;

    @Column(name = "updated_by_id", length = 36)
    private String updatedById;

    @Column(name = "updated_by_name", length = 150)
    private String updatedByName;

    // -------------------------------------------------------------------------
    // equals / hashCode based on id only — safe for JPA detached/managed state
    // -------------------------------------------------------------------------

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof BaseEntity other)) return false;
        return id != null && id.equals(other.id);
    }

    @Override
    public int hashCode() {
        return id == null ? System.identityHashCode(this) : id.hashCode();
    }
}

